package com.hmdp.ai.infrastructure.sandbox;
import com.fasterxml.jackson.databind.JsonNode;import com.hmdp.ai.domain.run.UsageSummary;import com.hmdp.ai.domain.tool.*;import org.springframework.stereotype.Component;import java.nio.file.Path;import java.util.Collections;
@Component public class SandboxToolProtocolAdapter implements ToolProtocolAdapter {private final SandboxWorkspaceService workspaces;private final DockerSandboxExecutor executor;public SandboxToolProtocolAdapter(SandboxWorkspaceService workspaces,DockerSandboxExecutor executor){this.workspaces=workspaces;this.executor=executor;}public ToolProtocol protocol(){return ToolProtocol.SANDBOX;}public ToolResult execute(ToolDefinition d,ToolInvocation i,JsonNode c){long started=System.currentTimeMillis();Path workspace=workspaces.create(i.getContext().getRunId());try{SandboxExecutor.SandboxExecution result=executor.execute(workspace,c,i.getInput(),i.getContext(),d.getTimeoutMs());return ToolResult.success(result.getData(),Collections.emptyList(),result.getArtifacts(),Collections.emptyList(),UsageSummary.empty(System.currentTimeMillis()-started));}catch(Exception e){String code=code(e);return ToolResult.failure(code.equals("SANDBOX_TIMEOUT")?ToolCallStatus.TIMED_OUT:ToolCallStatus.FAILED,code,"sandbox execution failed",false);}}private String code(Exception e){Throwable c=e;while(c!=null){if(c.getMessage()!=null&&c.getMessage().matches("[A-Z0-9_]+"))return c.getMessage();c=c.getCause();}return "SANDBOX_EXECUTION_FAILED";}}
